const BASE_URL = "/index.cgi";
const fetchApi = async (endpoint, options = {}) => {
  const token = localStorage.getItem("erph_token");
  const isFormData = options.body instanceof FormData;
  const headers = {
    ...isFormData ? {} : { "Content-Type": "application/json" },
    ...token ? { "Authorization": `Bearer ${token}` } : {},
    ...options.headers
  };
  const response = await fetch(`${BASE_URL}/api${endpoint}`, { ...options, headers });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`API Error ${response.status}: ${response.statusText} - ${errorText.substring(0, 200)}`);
  }
  return response.json();
};
const api = {
  auth: {
    login: (credentials) => fetchApi("/auth/login", { method: "POST", body: JSON.stringify(credentials) }),
    logout: () => {
      localStorage.removeItem("erph_token");
    },
    getProfile: () => fetchApi("/auth/profile")
  },
  lessonPlans: {
    list: (params) => fetchApi(`/lesson-plans?${new URLSearchParams(params)}`),
    get: (id) => fetchApi(`/lesson-plans/${id}`),
    save: (data) => fetchApi("/lesson-plans", { method: "POST", body: JSON.stringify(data) }),
    delete: (id) => fetchApi(`/lesson-plans/${id}`, { method: "DELETE" })
  },
  cms: {
    getArticles: (params) => fetchApi(`/articles?${new URLSearchParams(params)}`),
    getArticle: (slug) => fetchApi(`/articles/${slug}`),
    triggerCrawl: () => fetchApi("/cms/crawl", { method: "POST" }),
    notifications: {
      get: (userId) => fetchApi(`/notifications/${userId}`),
      markRead: (id) => fetchApi(`/notifications/${id}/read`, { method: "POST" })
    },
    auth: {
      getGoogleUrl: () => fetchApi("/auth/google/url"),
      connectGoogle: (code, userId) => fetchApi("/auth/google/callback", {
        method: "POST",
        body: JSON.stringify({ code, userId })
      })
    },
    user: {
      backupToDrive: (userId) => fetchApi("/backup/drive", {
        method: "POST",
        body: JSON.stringify({ userId })
      })
    }
  },
  admin: {
    createSchool: (formData) => fetchApi("/admin/schools", {
      method: "POST",
      body: formData,
      headers: {}
    }),
    sendNewsletter: (data) => fetchApi("/admin/newsletter/send", { method: "POST", body: JSON.stringify(data) }),
    getSettings: () => fetchApi("/admin/settings"),
    updateSettings: (data) => fetchApi("/admin/settings", { method: "PUT", body: JSON.stringify(data) }),
    getSchools: () => fetchApi("/admin/schools"),
    getUsers: (params) => fetchApi(`/admin/users?${new URLSearchParams(params)}`)
  },
  tasks: {
    list: () => fetchApi("/tasks"),
    updateStatus: (id, status) => fetchApi(`/tasks/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) })
  },
  dskp: {
    list: (params) => fetchApi(`/dskp?${new URLSearchParams(params)}`),
    getOptions: () => fetchApi("/dskp/options"),
    listStructure: () => fetchApi("/dskp/structure"),
    updateNode: (id, data) => fetchApi(`/dskp/${id}`, { method: "PUT", body: JSON.stringify(data) }),
    delete: (id) => fetchApi(`/dskp/${id}`, { method: "DELETE" }),
    sync: (data) => fetchApi("/dskp/sync", { method: "POST", body: JSON.stringify(data) })
  },
  users: {
    check: (email) => fetchApi(`/users/check?email=${encodeURIComponent(email)}`)
  },
  leave: {
    list: (params) => fetchApi(`/leaves?${new URLSearchParams(params)}`),
    create: (data) => fetchApi("/leaves", { method: "POST", body: JSON.stringify(data) }),
    delete: (id) => fetchApi(`/leaves/${id}`, { method: "DELETE" })
  }
};

